import {CARDS,TERRAINS,SKILLS,newState,loadState,saveState,createRun,createTutorial,getAfterglowRules,getAfterglowState,drawAfterglow,getPowerDiscovery,getChoices,selectNode,applyStarter,takeCard,finishFlight,getSupportChoices,resolveSupport,bankRun,buySkill,getSkillCost,getModifiers} from './model.mjs';
import {WispFlight} from './flight.mjs';
import { WISP_TUNING } from './wisp.mjs';
import { FLAME_TUNING } from './vitality.mjs';

const app=document.querySelector('#app'),header=document.querySelector('#header');
let state;try{state=loadState(localStorage)}catch{state=newState()}
let screen='home',engine=null,pendingCard=null,replaceIndex=0,lastSnapshot=null,paused=false,boostTimer=null,boostHeld=false,swipeX=0;
let muted=false;try{muted=localStorage.getItem('emberwing-muted')==='true'}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cardList=()=>Object.values(CARDS),skillList=()=>Object.values(SKILLS);
const cardById=id=>CARDS[id]||cardList().find(c=>c.id===id);
const iconPaths={
 flame:'<path d="M12 2c1 6 7 6 7 12a7 7 0 0 1-14 0c0-3 2-5 4-7-1 4 0 6 2 7-2-5 1-8 1-12Z"/><path d="M12 12c0 3 3 3 3 6a3 3 0 0 1-6 0c0-2 2-3 3-6Z"/>',
 wing:'<path d="M9 3h6v3h3v6h3v6h-3v3H6v-3H3v-6h3V6h3Z"/><path d="M9 12v3m6-3v3"/>',
 route:'<path d="M6 20V9a4 4 0 0 1 4-4h8M6 14h8a4 4 0 0 1 4 4v2"/><circle cx="6" cy="20" r="2"/><path d="m15 2 3 3-3 3"/><circle cx="18" cy="20" r="2"/>',
 cards:'<rect x="7" y="3" width="13" height="17" rx="2"/><path d="m4 5-2 1 3 16 11-2M13.5 7 16 11l-2.5 4L11 11l2.5-4Z"/>',
 ember:'<path d="m12 2 6 8-6 12-6-12 6-8Z"/><path d="M6 10h12m-6-8v20"/>',
 arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',
 star:'<path d="m12 2 2.7 6.3 6.8.7-5.1 4.5 1.5 6.5-5.9-3.5L6.1 20l1.5-6.5L2.5 9l6.8-.7L12 2Z"/>',
 shield:'<path d="m12 2 8 3v6c0 5-4 8-8 11-4-3-8-6-8-11V5l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 wisp:'<path d="M12 3c-5 4-8 7-8 11a8 8 0 0 0 16 0c0-3-2-6-5-8 1 4-1 6-3 7 1-4 1-7 0-10Z"/><circle cx="10" cy="15" r=".7"/><circle cx="15" cy="15" r=".7"/>',
 wind:'<path d="M3 8h11a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M5 17h6a2 2 0 1 1-2 2"/>',
 leaf:'<path d="M20 3C7 2 2 7 4 15c8 5 16 0 16-12Z"/><path d="M3 21 17 7M8 16l1-7m4 2h5"/>',
 ruins:'<path d="M3 21h18M4 7h16M7 7v14m10-14v14M3 7l9-5 9 5M5 11h4m6 0h4"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 sound:'<path d="m11 4-6 5H2v6h3l6 5V4Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
 mute:'<path d="m11 4-6 5H2v6h3l6 5V4Zm5 5 5 6m0-6-5 6"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
 moon:'<path d="M20.5 14A9 9 0 0 1 10 3a9 9 0 1 0 10.5 11Z"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>'
};
function icon(name,cls=''){const k=({'✧':'wisp','✦':'sun','◈':'ember','ϟ':'wind','⌄':'wing','⌃':'wing','»':'wind','◇':'shield','♢':'heart','≈':'wind','♨':'flame','♡':'heart',boost:'flame',survival:'shield',collection:'wisp',mobility:'wing',spirit:'wisp',ash:'shield',speed:'wind',phoenix:'flame',rebirth:'sun',control:'wing'}[String(name).toLowerCase()]||name);return `<svg class="ico ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[k]||iconPaths.star}</svg>`}
function terrainInfo(id){const t=TERRAINS[id]||{};return {name:t.name||({ruins:'Ancient Ruins',canopy:'Luminous Canopy',storm:'Storm Spires'}[id]),icon:{ruins:'ruins',canopy:'leaf',storm:'wind'}[id]||'flame'}}
function heartMarkup(hp,max=3){return `<span class="hearts" aria-label="${hp} of ${max} health">${Array.from({length:max},(_,i)=>icon('heart',i<hp?'':'empty')).join('')}</span>`}
function notify(message){const e=document.querySelector('#toast');e.textContent=message;e.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>e.classList.remove('show'),2800)}
function persist(){try{if(!saveState(state,localStorage)&&!persist.warned){persist.warned=true;notify('Storage is unavailable. Keep this tab open to retain progress.')}}catch{if(!persist.warned){persist.warned=true;notify('Storage is unavailable. Keep this tab open to retain progress.')}}}
function destroyFlight(){if(engine){engine.destroy();engine=null}document.body.classList.remove('playing');clearTimeout(boostTimer)}
function navigate(view){closePower();destroyFlight();screen=view;pendingCard=null;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){document.body.dataset.screen=screen;document.body.dataset.element=state.settings.element||'fire';document.body.classList.toggle('playing',screen==='flight');renderHeader();const views={home:renderHome,map:renderMap,cards:renderCards,replace:renderReplace,support:renderSupport,briefing:renderBriefing,skills:renderSkills,codex:renderCodex,result:renderResult};app.innerHTML=(views[screen]||renderHome)();app.classList.remove('enter');void app.offsetWidth;app.classList.add('enter');if(screen==='map')drawMap();if(screen==='replace')bindSwipe()}
function goToRun(){if(!state.run){navigate('home');return}let p=state.run.phase;if(p==='flight'){state.run.phase='briefing';p='briefing'}if(p==='ended'){bankRun(state);persist();navigate('result')}else navigate(({starter:'cards',reward:'cards',map:'map',briefing:'briefing',support:'support'}[p])||'map')}
function beginRun(practice=false,regular=false){if(state.run&&state.run.phase!=='ended'){goToRun();return}state.run=practice||(!regular&&!state.profile.tutorialComplete)?createTutorial(state.profile):createRun(state.profile);state.run.element=state.settings.element||'fire';persist();goToRun()}
function runLength(run=state.run){return run?.map?.length||7}
function mapHeight(run=state.run){return runLength(run)*145+225}
function skipTutorial(){if(!state.run?.isTutorial)return;destroyFlight();state.run.phase='ended';state.run.success=false;bankRun(state);state.profile.tutorialComplete=true;persist();beginRun(false,true)}
function reserveNumber(value){return Math.round((Number(value)||0)*100)/100}
function afterglowPanel({draw=false,home=false}={}){if(state.run?.isTutorial&&state.run.step===0&&state.run.phase!=='reward')return '';if(home&&!state.profile.tutorialComplete&&!state.profile.clearedFlights&&!state.profile.afterglow)return '';const reserve=getAfterglowState(state),amount=reserveNumber(reserve.amount),cap=reserve.cap||40,drawable=reserveNumber(reserve.drawable);return `<div class="afterglow-panel ${home?'home-afterglow':''} ${reserve.practice?'practice-reserve':''}"><button class="afterglow-readout" data-action="inspect-afterglow" aria-label="${reserve.practice?'Practice ':''}Afterglow ${amount} of ${cap}. Reserve information"><span class="afterglow-name">${icon('moon')}${reserve.practice?'Practice':'Afterglow'}</span><span class="afterglow-pips" aria-hidden="true">${Array.from({length:8},(_,i)=>`<i><b style="width:${Math.min(100,Math.max(0,(amount/cap*8-i)*100))}%"></b></i>`).join('')}</span><strong>${amount}<small>/${cap}</small></strong>${icon('info')}</button>${draw?`<button class="afterglow-draw" data-action="draw-afterglow" ${!drawable?'disabled':''}>${reserve.drawUsed?'Draw used':`Draw +${drawable} Glow`}</button>`:''}</div>`}
function inspectAfterglow(){if(screen==='flight')return;closePower();const r=getAfterglowState(state),pct=n=>Math.round((n||0)*100),returnFocus=document.activeElement,sheet=document.createElement('dialog');sheet.id='power-inspector';sheet.className='power-sheet afterglow-sheet';sheet.setAttribute('aria-labelledby','power-sheet-name');sheet.innerHTML=`<div class="power-sheet-title">${icon('moon')}<h2 id="power-sheet-name">${r.practice?'Practice ':''}Afterglow</h2></div><div class="reserve-sheet-values"><span><b>${reserveNumber(r.amount)}/${r.cap}</b>stored</span><span><b>${pct(r.retention)}%</b>retained</span><span><b>−${pct(r.failureLoss)}%</b>on defeat</span></div><p class="power-sheet-stats">Draw up to ${r.drawLimit} Glow once before each flight.</p><p class="power-sheet-note">Spare Glow above 60 feeds this reserve after a successful flight. Holding it for a later route is your choice.${r.practice?' This practice reserve never changes your real Afterglow.':' The reserve carries between expeditions; defeat or abandoning the expedition reduces it once.'}</p><button class="primary" data-action="close-power">Close</button>`;sheet.addEventListener('close',()=>{sheet.remove();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})},{once:true});document.body.appendChild(sheet);if(typeof sheet.showModal==='function')sheet.showModal();else sheet.setAttribute('open','');sheet.querySelector('button').focus()}
function discoveryProgress(){const r=state.run;if(r?.isTutorial&&r.phase!=='ended')return '';const d=getPowerDiscovery(state);return d.nextAt?`<div class="discovery-progress" aria-label="${d.cleared} of ${d.nextAt} flights toward ${d.nextIds.length} new powers">${icon('cards')}<span>${d.cleared}/${d.nextAt}</span><i><b style="width:${Math.min(100,d.cleared/d.nextAt*100)}%"></b></i><span>+${d.nextIds.length} powers</span></div>`:''}
function afterglowChange(values){if(!values)return '';const bits=[];if(values.stored)bits.push(`<span>${icon('moon')}+${reserveNumber(values.stored)} stored</span>`);if(values.loss)bits.push(`<span class="reserve-loss">${icon('moon')}−${reserveNumber(values.loss)} lost</span>`);return bits.length?`<div class="afterglow-change">${bits.join('')}</div>`:''}
function discoveryCue(){const ids=state.run?.lastFlight?.unlockedPowers||[];return ids.length?`<div class="discovery-unlocked"><b>NEW</b>${ids.map(id=>`<span>${esc(cardById(id)?.name||id)}</span>`).join('')}</div>`:''}
function tutorialCheckpoint(){return state.run?.isTutorial?`<div class="tutorial-checkpoint"><span>${icon('wing')}Practice</span><button data-action="skip-tutorial">Skip ${icon('arrow')}</button></div>`:''}

function miniCards(cards){return `<div class="slot-list">${Array.from({length:3},(_,i)=>{const c=cardById(cards[i]);return c?`<button class="mini-card equipped-power" data-action="inspect-power" data-id="${esc(c.id)}" aria-label="Inspect power: ${esc(c.name)}" style="--card:${esc(c.color||'#d9bd83')}">${cardArt(c)}<h4>${esc(c.name)}</h4><span class="power-inspect-dot" aria-hidden="true">i</span></button>`:`<div class="mini-card empty" aria-label="Empty power slot"><b>+</b></div>`}).join('')}</div>`}
function runStats(){const r=state.run,total=runLength(r);return `<div class="run-info">${heartMarkup(r.hp,r.maxHp||3)}<span class="stat">${icon('ember')}${Math.floor(r.embers||0)}</span><span class="pill">Stop ${Math.min(r.step+1,total)} / ${total}</span></div>`}
function powerInfo(c){return ({
 'hungry-wisp':{action:'Boost → farther fetches',stats:'Carrier reach +60% during Boost',icon:'wisp',note:'The carrier’s dotted reach circle expands during Boost.'},
 'kindled-spirit':{action:'Pickups → faster Boost',stats:'Every 3 Glow pickups: Boost ready 1s sooner.',icon:'flame',note:'Bonus motes do not advance this counter.'},
 'golden-wake':{action:'Boost + pickup → score',stats:'×2 pickup score only.',icon:'star',note:'Score is your expedition total. This adds no Glow or embers.'},
 'storm-feeder':{action:'Gusts → faster Boost',stats:'Boost ready 4% sooner. Gusts shave off 1s each second.',icon:'wind'},
 'soft-descent':{action:'Always → gentler drift',stats:'Gravity 10% lighter · Lift 6% weaker',icon:'wing'},
 'high-wing':{action:'Lift → higher rise',stats:'Lift 10% stronger · Travel 5% faster',icon:'wing'},
 tailwind:{action:'Always → faster, richer',stats:'Travel 8% faster · Pickup embers +12%',icon:'ember',note:'Embers buy permanent upgrades. This adds no Glow.'},
 'ash-ward':{action:'First hit → blocked',stats:'Blocks 1 hit each flight. Boost recharges 12% slower.',icon:'shield'},
 'glass-phoenix':{action:'Trade health → more embers',stats:'Max HP 2 · Pickup embers +25%',icon:'heart',note:'Replacing this power restores health capacity, not lost hearts.'},
 'steady-flame':{action:'Gusts → steadier flight',stats:'Gusts 55% weaker · Gravity 3% lighter',icon:'wind'},
 'fire-wake':{action:'Boost → shatter soft thorns',stats:'Boost 8% longer · Soft thorn: 3 bonus Glow motes',icon:'flame',note:'Only designated soft thorns shatter. Solid terrain remains dangerous. Bonus motes do not trigger pickup powers.'},
 'warm-heart':{action:'Pickups → heal',stats:'4 Glow pickups → +1 HP, once each flight',icon:'heart',note:'Rich and ordinary caches each count as one pickup. Bonus motes are excluded. The heal is spent even at full health.'},
 })[c?.id]||{action:c?.description||'',stats:c?.detail||'',icon:'cards'}}
function shortCard(c){return powerInfo(c).stats}
function cardMarkup(c,{action='',extra=''}={}){if(!c)return '';const power=powerInfo(c);return `<${action?'button':'article'} class="game-card" ${action?`data-action="${action}" data-id="${esc(c.id)}" aria-label="${esc(c.name)}. ${esc(power.action)}. ${esc(power.stats)}"`:''} style="--card:${esc(c.color||'#dfbd83')}"><span class="card-emblem">${cardArt(c)}</span><span class="card-tag">${esc(c.tag||'Spirit')} POWER${state.run?.lastFlight?.unlockedPowers?.includes(c.id)?'<b class="new-power-badge">NEW</b>':''}</span><h3>${esc(c.name)}</h3><p class="power-action">${icon(power.icon)}<span>${esc(power.action)}</span></p><p class="power-numbers">${esc(power.stats)}</p>${extra}</${action?'button':'article'}>`}
function inspectPower(id){if(screen==='flight')return;const c=cardById(id);if(!c)return;closePower();const power=powerInfo(c),returnFocus=document.activeElement,sheet=document.createElement('dialog');sheet.id='power-inspector';sheet.className='power-sheet';sheet.setAttribute('aria-labelledby','power-sheet-name');sheet.innerHTML=`<div class="power-sheet-title">${cardArt(c)}<h2 id="power-sheet-name">${esc(c.name)}</h2></div><div class="power-sheet-action">${icon(power.icon)}<span>${esc(power.action)}</span></div><p class="power-sheet-stats">${esc(power.stats)}</p>${power.note?`<p class="power-sheet-note">${esc(power.note)}</p>`:''}<div class="power-sheet-duration">${icon('cards')}Automatic · this expedition</div><button class="primary" data-action="close-power">Close</button>`;sheet.addEventListener('close',()=>{sheet.remove();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})},{once:true});document.body.appendChild(sheet);if(typeof sheet.showModal==='function')sheet.showModal();else sheet.setAttribute('open','');sheet.querySelector('button').focus()}
function closePower(){const sheet=document.querySelector('#power-inspector');if(!sheet)return;if(typeof sheet.close==='function'&&sheet.open)sheet.close();else sheet.remove()}
function renderCards(){const r=state.run;return `<section class="center-view compact-reward"><h1>Choose a power</h1><div class="power-draft-cue">Automatic · this expedition · 3 slots</div>${rewardBanner()}${afterglowPanel()}${discoveryProgress()}<div class="card-offers">${r.offers.map(id=>cardMarkup(cardById(id),{action:'card'})).join('')}</div>${r.cards.length?`<section class="loadout"><div class="loadout-head"><span>${icon('cards')}</span><span>${r.cards.length}/3</span></div>${miniCards(r.cards)}</section>`:''}</section>`}
function renderReplace(){const incoming=cardById(pendingCard),old=cardById(state.run.cards[replaceIndex]);return `<section class="center-view compact-replace"><h1>Replace a power</h1><div class="replace-incoming">${cardArt(incoming)}<div><strong>${esc(incoming.name)}</strong><p>${esc(shortCard(incoming))}</p></div></div><div class="replace-arrow">↓</div><div class="replacement" id="replace-swipe">${cardMarkup(old)}<div class="carousel-dots">${state.run.cards.map((_,i)=>`<i class="carousel-dot ${i===replaceIndex?'active':''}"></i>`).join('')}</div><div class="small subtle">← ${replaceIndex+1}/3 →</div></div><div class="two-actions"><button class="secondary" data-action="keep">Keep ${icon('ember')}+8</button><button class="primary" data-action="replace">Replace ${icon('arrow')}</button></div></section>`}
function bindSwipe(){const e=document.querySelector('#replace-swipe');e.addEventListener('pointerdown',ev=>swipeX=ev.clientX);e.addEventListener('pointerup',ev=>{const dx=ev.clientX-swipeX;if(Math.abs(dx)>30){replaceIndex=(replaceIndex+(dx<0?1:2))%3;render()}})}
function renderSupport(){const r=state.run,n=r.current,choices=getSupportChoices(r);const effect=e=>{const bits=[];for(const [key,symbol]of[['hp','heart'],['shield','shield'],['flame','flame'],['embers','ember'],['score','star']])if(e[key])bits.push(`<span class="${e[key]<0?'boon-cost':''}">${icon(symbol)}${key==='flame'&&e[key]>=100?'100':`${e[key]>0?'+':'−'}${Math.abs(e[key])}`}</span>`);if(e.draft)bits.push(`<span>${icon('cards')}1</span>`);return bits.join('')};const names={rest:'Rest',gather:'Gather',spring:'Drink','spring-gold':'Gather',bargain:'Bargain','bargain-shield':'Ward','bargain-safe':'Gather','nest-ward':'Ward','nest-gold':'Gather','shrine-draft':'New spark','shrine-keep':'Gather',well:'Restore','well-gold':'Gather','archive-draft':'New spark','archive-rest':'Rest','shrine-fuel':'Refill','shrine-inspiration':'New spark'};return `<section class="center-view compact-support">${tutorialCheckpoint()}<div class="support-symbol"></div><h1>${esc(n.name)}</h1><div class="support-vitals">${heartMarkup(r.hp,r.maxHp||3)}<span>${icon('flame')}${Math.round(r.flame??100)}</span><span>${icon('ember')}${Math.floor(r.embers||0)}</span></div>${afterglowPanel()}${discoveryProgress()}<div class="support-offers">${choices.map((c,i)=>`<button class="route-choice boon-choice" data-action="support" data-index="${i}" aria-label="${esc(c.title)}. ${esc(c.description)}"><span class="boon-emblem">${icon(c.effect?.draft?'cards':c.effect?.hp?'heart':c.effect?.shield?'shield':c.effect?.flame?'flame':'ember')}</span><h3>${names[c.id]||esc(c.title)}</h3><div class="boon-values">${effect(c.effect||{})}</div></button>`).join('')}</div></section>`}
function modifierText(){const r=state.run,m=getModifiers(r.cards,state.profile.skills),bits=[];if(Math.abs(m.speed-1)>.01)bits.push(`Travel ${m.speed>1?'+':''}${Math.round((m.speed-1)*100)}%`);if(Math.abs(m.flap-1)>.01)bits.push(`Lift ${m.flap>1?'+':''}${Math.round((m.flap-1)*100)}%`);if(Math.abs(m.gravity-1)>.01)bits.push(`Gravity ${m.gravity>1?'+':''}${Math.round((m.gravity-1)*100)}%`);return bits.join(' · ')||'Balanced flight · familiar controls'}
function renderBriefing(){const r=state.run,n=r.current,t=terrainInfo(n.terrain),art={ruins:0,canopy:1,storm:2}[n.terrain]??0,low=(r.flame??100)<(n.elite?70:n.passage==='cavern'?60:35),badge=n.type==='finale'?'FINAL':n.elite?'ELITE':n.passage==='cavern'?'CAVERN':'REFUGE';return `<section class="center-view compact-briefing">${tutorialCheckpoint()}<div class="encounter-art terrain-${esc(n.terrain)}"><span class="map-route-illustration" style="background-position:${art*50}% 0" aria-hidden="true"></span><span class="encounter-badge ${n.elite?'danger':''}">${badge}</span></div><h1>${esc(n.name)}</h1><div class="brief-stats"><div>${icon('heart')}<strong>${r.hp}/${r.maxHp||3}</strong></div><div>${icon('flame')}<strong>${Math.round(r.flame??100)}</strong></div><div>${icon('wing')}<strong>−${Math.round(7*(n.flameDrain||1))}</strong></div></div><div class="encounter-loot"><span>${icon('wisp')}+${FLAME_TUNING.emberFuel+(n.fuelBonus||0)}</span><span>${icon('ember')}×${Number(n.routeReward||1).toFixed(2)}</span><span>${icon('cards')}${esc(n.draftTheme||'Spark')}</span></div><div class="encounter-fuel">${n.fuelCadence<=2?'●●●':n.fuelCadence>=4?'●○○':'●●○'}<span>FUEL</span><span class="encounter-wind" aria-label="Wind exposure">${icon('wind')}${'●'.repeat(Math.max(1,(n.terrain==='storm'?3:n.terrain==='canopy'?2:1)-(n.passage==='cavern'?1:0)))}</span><span>≈${n.duration||38}s</span></div>${low?`<div class="route-readiness low-glow-warning">${icon('flame')} LOW GLOW</div>`:''}<div class="encounter-challenge">${icon('star')}${esc(n.challenge||'Reach the gate')}${n.challengeBonus?`<span>+${n.challengeBonus}${icon('ember')}</span>`:''}</div>${afterglowPanel({draw:true})}${discoveryProgress()}<button class="primary enter-passage" data-action="launch">Enter ${icon('arrow')}</button><section class="loadout">${miniCards(r.cards)}</section><details class="game-help"><summary aria-label="Flight controls and resource rules">?</summary><div>Tap Lift to rise. Tap Boost to surge and resist gusts; hold it to pause.<br><br>Glow pickups refill Lift fuel. Your carrier fetches one, returns, then rests ${WISP_TUNING.cooldown}s. Power cards trigger automatically for this expedition.<br><br>Progress is saved in this browser.</div></details></section>`}
function renderSkills(){const branches=[{name:'Spirit',key:'wisp',icon:'wisp'},{name:'Boost',key:'boost',icon:'flame'},{name:'Rebirth',key:'rebirth',icon:'sun'},{name:'Afterglow',key:'afterglow',icon:'moon'}],inRun=state.run&&state.run.phase!=='ended';const effects={'wisp-light':'Sight +35 per rank','wisp-reach':'Fetch range +25% per rank','wisp-recovery':'Carrier rest −15% per rank','wisp-bounty':'Pickup embers +10%','boost-focus':'Boost cooldown −10%','boost-flare':'Boost duration +15%','rebirth-spark':'1 revive · 1 HP','rebirth-grace':'Revive restores 2 HP','afterglow-vessel':'Reserve capacity +15 per rank','afterglow-retention':'Spare Glow retained +10 points per rank','afterglow-anchor':'Defeat loss −10 points per rank'};return `<section class="compact-skills"><div class="compact-page-title"><h1>Ascension</h1><span>${icon('ember')}${state.profile.embers||0}</span></div>${inRun?'<div class="between-runs">Upgrades unlock between runs</div>':''}<div class="skill-branches">${branches.map(b=>`<section class="skill-branch"><div class="branch-head">${icon(b.icon)}<h2>${b.name}</h2>${b.key==='afterglow'?`<span class="branch-preview">${getAfterglowRules(state.profile.skills).cap} cap · ${Math.round(getAfterglowRules(state.profile.skills).retention*100)}% kept · ${Math.round(getAfterglowRules(state.profile.skills).failureLoss*100)}% loss</span>`:''}</div>${skillList().filter(s=>s.id.startsWith(b.key)).map(skill=>{const rank=state.profile.skills[skill.id]||0,max=skill.maxRank||1,complete=rank>=max,cost=getSkillCost(state.profile,skill.id),req=skill.requires?Array.isArray(skill.requires)?skill.requires:[skill.requires]:[],locked=req.some(id=>!state.profile.skills[id]);return `<div class="skill-node ${rank?'owned':''}"><div class="skill-node-copy"><h3>${esc(skill.name)}</h3><p>${effects[skill.id]||esc(skill.description)}</p><div class="rank-pips" aria-label="Rank ${rank} of ${max}">${Array.from({length:max},(_,i)=>`<i class="${i<rank?'filled':''}"></i>`).join('')}</div></div>${complete?`<span class="skill-complete">${icon('check')}</span>`:`<button class="${!locked&&!inRun&&state.profile.embers>=cost?'primary':'secondary'}" data-action="buy-skill" data-id="${esc(skill.id)}" aria-label="Upgrade ${esc(skill.name)} for ${cost} embers" ${locked||inRun||state.profile.embers<cost?'disabled':''}>${icon('ember')}${cost}</button>`}</div>`}).join('')}</section>`).join('')}</div></section>`}
function renderCodex(){const discovery=getPowerDiscovery(state),unlocked=new Set(discovery.unlocked),cards=cardList().filter(c=>unlocked.has(c.id));return `<section class="compact-page-title"><h1>Grimoire</h1><span>${icon('cards')}${cards.length}/${cardList().length}</span></section>${discoveryProgress()}<div class="codex-grid">${cards.map(c=>cardMarkup(c)).join('')}</div>`}
function renderResult(){const r=state.run,total=runLength(r);return `<section class="center-view compact-result"><div class="result-symbol">${icon(r.success?'sun':'wisp')}</div><h1>${r.isTutorial?(r.success?'First flight complete':'Practice ended'):(r.success?'Gate reached':'Light fades')}</h1>${r.isTutorial?'<div class="practice-result">Practice · your real reserve is safe</div>':''}<div class="result-stats"><div><strong>${Math.floor(r.embers||0)}</strong><span>${icon('ember')}${r.isTutorial?'practice':''}</span></div><div><strong>${Math.floor(r.score||0)}</strong><span>${icon('star')}</span></div><div><strong>${r.success?total:r.step}/${total}</strong><span>${icon('route')}</span></div></div>${r.isTutorial?'':afterglowChange(r.afterglowTotals)}${afterglowPanel()}${discoveryCue()}<div class="result-loadout">${miniCards(r.cards)}</div>${r.isTutorial?`<button class="primary tutorial-play" data-action="begin-regular">Play ${icon('arrow')}</button>`:`<div class="two-actions"><button class="secondary" data-action="skills">Ascend ${icon('sun')}</button><button class="primary" data-action="begin">Again ${icon('arrow')}</button></div>`}</section>`}
function launch(){destroyFlight();screen='flight';paused=false;renderHeader();document.body.classList.add('playing');const r=state.run,n=r.current,t=terrainInfo(n.terrain);app.innerHTML=`<section class="flight-shell"><div class="flight-device"><div class="flight-hud"><div><div class="flight-title">${r.step+1}/${runLength(r)} · ${esc(t.name)}</div><div id="flight-health">${heartMarkup(r.hp,r.maxHp)}</div></div><div class="flight-topstats"><span>${icon('ember')}<b id="flight-embers">0</b></span><span>${icon('star')}<b id="flight-score">0</b></span></div></div><div class="flame-hud"><span>${icon('flame')}</span><div id="flame-meter" role="meter" aria-label="Glow" aria-valuemin="0" aria-valuemax="100"><i id="flame-fill"></i></div><b id="flame-value">100</b></div><div class="flight-progress"><i id="flight-progress-bar"></i></div><div class="canvas-wrap"><canvas id="flight-canvas" aria-label="Wisp playfield. Lift and Boost are below on the right."></canvas><div class="flight-event" id="flight-event"></div>${r.isTutorial?'<div class="tutorial-flight-hint" id="tutorial-hint" aria-live="polite"></div>':''}<div class="wisp-hud" id="wisp-hud" aria-label="Carrier ready"><i></i><span id="wisp-status">100</span></div></div><div class="flight-dock"><div class="flight-mobile-cards">${Array.from({length:3},(_,i)=>r.cards[i]?`<span title="${esc(cardById(r.cards[i]).name)}">${cardArt(cardById(r.cards[i]))}</span>`:'<span class="empty">+</span>').join('')}</div><button class="flight-control boost-control" id="boost-btn" aria-label="Boost; hold to pause">${icon('flame')}<span id="boost-label" class="cooldown-label">BOOST</span></button><button class="flight-control flap-control" id="flap-btn" aria-label="Lift upward">${icon('wing')}<span id="flap-label">LIFT −${Math.round(7*(n.flameDrain||1))}</span></button></div><div id="pause-layer"></div></div></section>`;document.body.dataset.element=r.element||state.settings.element||'fire';const mods=getModifiers(r.cards,r.skills||state.profile.skills);engine=new WispFlight({canvas:document.querySelector('#flight-canvas'),terrain:n.terrain,elite:n.elite,seed:`${r.seed}-${n.id}`,duration:n.duration||38,challengeId:n.challengeId,challengeTarget:n.challengeTarget,cards:r.cards,skills:r.skills||state.profile.skills,modifiers:mods,node:n,hp:r.hp,flame:r.flame??100,maxHp:r.maxHp||mods.maxHp,shield:r.shield||0,rebirthAvailable:!!mods.rebirth&&!r.usedRebirth,element:r.element||state.settings.element||'fire',onUpdate:updateFlight,onFinish:completeFlight,onPause:p=>{if(p&&!paused){paused=true;showPause()}}});engine.setMuted?.(muted);bindControls();engine.start()}
function updateFlight(s){lastSnapshot=s;const health=document.querySelector('#flight-health');if(!health)return;health.innerHTML=heartMarkup(Math.max(0,Math.ceil(s.hp)),s.maxHp||state.run.maxHp||3);document.querySelector('#flight-embers').textContent=Math.floor(s.embers||0);document.querySelector('#flight-score').textContent=Math.floor(s.score||0);document.querySelector('#flight-progress-bar').style.width=`${Math.min(100,(s.progress||0)*100)}%`;const boost=document.querySelector('#boost-btn'),cool=s.boostCooldown||0;boost.classList.toggle('cooling',cool>.05);document.querySelector('#boost-label').textContent=cool>.05?`${cool.toFixed(1)}s`:'BOOST';const spirit=s.wisp;if(spirit){const status=document.querySelector('#wisp-status'),hud=document.querySelector('#wisp-hud');status.textContent=spirit.phase==='cooldown'?`${spirit.cooldown.toFixed(1)}s`:spirit.phase==='outbound'?'FETCH':spirit.phase==='returning'?(spirit.carrying?`+${spirit.cargoValue||1}`:'RETURN'):`R${Math.round(spirit.radius)}`;hud.dataset.phase=spirit.phase;hud.setAttribute('aria-label',`Carrier ${spirit.phase}. ${spirit.phase==='cooldown'?`${spirit.cooldown.toFixed(1)} seconds`: `Range ${Math.round(spirit.radius)}`}`)}const vitality=Math.round(s.flame??100),meter=document.querySelector('#flame-meter');meter.setAttribute('aria-valuenow',String(vitality));document.querySelector('#flame-fill').style.transform=`scaleX(${vitality/100})`;document.querySelector('#flame-value').textContent=vitality;const exhausted=s.canFlap===false;document.querySelector('.flight-device').classList.toggle('low-flame',vitality<=21);document.querySelector('.flight-device').classList.toggle('exhausted',exhausted);const flap=document.querySelector('#flap-btn');flap.setAttribute('aria-disabled',String(exhausted));flap.setAttribute('aria-label',exhausted?'No Glow. Touch a spark to lift.':`Lift. Costs ${s.flapCost||7} Glow.`);document.querySelector('#flap-label').textContent=exhausted?'GLIDE':`LIFT −${s.flapCost||7}`;document.querySelector('#flight-event').textContent=s.event||(exhausted?'GLOW EMPTY':vitality<=21?'LOW GLOW':'');const tutorial=document.querySelector('#tutorial-hint'),hint=s.tutorialHintState;if(tutorial){tutorial.hidden=!hint;if(hint){const key=`${hint.id}|${hint.title}|${hint.text}`;if(tutorial.dataset.hint!==key){tutorial.dataset.hint=key;tutorial.innerHTML=`<span>${hint.step||1}/${hint.total||1}</span><div><strong>${esc(hint.title)}</strong><p>${esc(hint.text)}</p></div>`}}}}
function completeFlight(result){const current=engine;engine=null;current?.destroy();finishFlight(state.run,result);persist();if(state.run.phase==='ended'){bankRun(state);persist()}goToRun()}
function bindControls(){const flap=document.querySelector('#flap-btn'),boost=document.querySelector('#boost-btn');flap.addEventListener('click',e=>{if(e.detail===0&&engine&&!paused)engine.flap()});boost.addEventListener('click',e=>{if(e.detail===0&&engine&&!paused)engine.boost()});flap.addEventListener('pointerdown',e=>{e.preventDefault();if(engine&&!paused)engine.flap()});boost.addEventListener('pointerdown',e=>{e.preventDefault();boost.setPointerCapture(e.pointerId);boostHeld=false;boostTimer=setTimeout(()=>{boostHeld=true;togglePause()},480)});boost.addEventListener('pointerup',e=>{e.preventDefault();clearTimeout(boostTimer);if(!boostHeld&&engine&&!paused)engine.boost()});boost.addEventListener('pointercancel',()=>clearTimeout(boostTimer));document.querySelector('.canvas-wrap').addEventListener('pointerdown',e=>{e.preventDefault();if(!paused)engine?.flap()})}
function showPause(){const e=document.querySelector('#pause-layer');if(!e)return;e.innerHTML=`<div class="pause-overlay"><h2>Paused</h2><button class="primary" data-action="resume">Resume ${icon('arrow')}</button><button class="secondary" data-action="leave-flight">Camp ${icon('moon')}</button></div>`}
function togglePause(){if(!engine)return;if(paused){paused=false;document.querySelector('#pause-layer').innerHTML='';engine.resume()}else{paused=true;engine.pause();showPause()}}
function acceptCard(id,slot=null){const r=state.run;if(r.phase==='starter')applyStarter(r,id);else takeCard(r,id,slot);pendingCard=null;persist();goToRun()}
function keepBuild(){const r=state.run;/* takeCard with a current card resolves a reward without changing slots. */if(typeof takeCard==='function')takeCard(r,null);persist();goToRun()}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;const action=btn.dataset.action,id=btn.dataset.id;switch(action){case'inspect-power':inspectPower(id);break;case'inspect-afterglow':inspectAfterglow();break;case'draw-afterglow':{const amount=drawAfterglow(state.run);if(amount){persist();render();notify(`+${amount} Glow`)}}break;case'learn':beginRun(true);break;case'skip-tutorial':skipTutorial();break;case'begin-regular':if(state.run?.isTutorial)state.profile.tutorialComplete=true;beginRun(false,true);break;case'close-power':closePower();break;case'element':state.settings.element=id==='ice'?'ice':'fire';persist();render();break;case'home':navigate('home');break;case'play':state.run&&state.run.phase!=='ended'?goToRun():navigate('home');break;case'continue':goToRun();break;case'begin':beginRun();break;case'restart':if(state.run&&state.run.phase!=='ended'){state.run.phase='ended';state.run.success=false;bankRun(state)}persist();beginRun();break;case'skills':navigate('skills');break;case'codex':navigate('codex');break;case'mute':muted=!muted;try{localStorage.setItem('emberwing-muted',String(muted))}catch{}engine?.setMuted?.(muted);renderHeader();notify(muted?'Sound muted':'Sound enabled');break;case'back-route':if(['briefing','support'].includes(state.run?.phase)){state.run.path.pop();state.run.current=null;state.run.phase='map';persist();goToRun()}else navigate('home');break;case'node':selectNode(state.run,id);persist();goToRun();break;case'card':if(state.run.cards.length>=3){pendingCard=id;replaceIndex=0;screen='replace';render();window.scrollTo({top:0,behavior:'instant'})}else acceptCard(id);break;case'replace':acceptCard(pendingCard,replaceIndex);break;case'keep':keepBuild();break;case'support':resolveSupport(state.run,Number(btn.dataset.index));persist();goToRun();break;case'launch':launch();break;case'buy-skill':if(buySkill(state.profile,id)){persist();const y=window.scrollY;render();window.scrollTo(0,y);notify('Your wisp grows stronger.')}break;case'resume':togglePause();break;case'leave-flight':destroyFlight();navigate('home');break}});
document.addEventListener('keydown',e=>{if(screen==='flight'&&engine){if(['Space','ArrowUp','KeyB','ShiftLeft','ShiftRight','Escape'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape')togglePause();else if(!paused&&['Space','ArrowUp'].includes(e.code))engine.flap();else if(!paused&&['KeyB','ShiftLeft','ShiftRight'].includes(e.code))engine.boost()}else if(screen==='replace'&&['ArrowLeft','ArrowRight'].includes(e.code)){replaceIndex=(replaceIndex+(e.code==='ArrowRight'?1:2))%3;render()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&engine&&!paused){paused=true;engine.pause();showPause()}});
window.addEventListener('orientationchange',()=>{if(engine&&!paused){paused=true;engine.pause();showPause()}});
window.addEventListener('pagehide',persist);
function renderHeader(){const r=state.run,active=r&&r.phase!=='ended',isHome=screen==='home',back=['briefing','support'].includes(screen);header.innerHTML=`<div class="game-top-left">${isHome?`<span class="header-wisp">${icon('wing')}</span>`:`<button class="game-round back-icon" data-action="${back?'back-route':'home'}" aria-label="${back?'Back to map':'Camp'}">${icon('arrow')}</button>`}</div><div class="header-end"><span class="bank" aria-label="${active?'Run':'Banked'} embers">${icon('ember')}<span>${Math.floor(active?r.embers:state.profile.embers)||0}</span></span><button class="game-round" data-action="mute" aria-label="${muted?'Enable':'Mute'} sound">${icon(muted?'mute':'sound')}</button></div>`}
function renderHome(){const active=state.run&&state.run.phase!=='ended';return `<section class="game-splash minimal-home"><div class="splash-scenery"></div><div class="wisp-hero" role="img" aria-label="Fire and Ice spirits"><i class="wisp-fire"></i><i class="wisp-ice"></i></div><div class="sparks">${Array.from({length:14},(_,i)=>`<i style="--x:${8+i*6}%;--t:${4+i%5}s;--d:${-i*.6}s"></i>`).join('')}</div><div class="game-title"><h1>WISPBOUND</h1></div><div class="game-home-bottom">${active?'':afterglowPanel({home:true})}<div class="element-pick" role="group" aria-label="${active?'Next run element':'Element'}"><button data-action="element" data-id="fire" class="${state.settings.element!=='ice'?'selected':''}" aria-pressed="${state.settings.element!=='ice'}">FIRE<span class="element-duo fire-duo" aria-hidden="true">◆ <i>◇</i></span></button><button data-action="element" data-id="ice" class="${state.settings.element==='ice'?'selected':''}" aria-pressed="${state.settings.element==='ice'}">ICE<span class="element-duo ice-duo" aria-hidden="true">◆ <i>◇</i></span></button></div><button class="game-play" data-action="${active?'continue':'begin'}">${icon('wing')}<span>${active?'CONTINUE':'PLAY'}</span>${icon('arrow')}</button><div class="game-menu-tools"><button data-action="skills" aria-label="Ascension"><span class="menu-medallion map-art-5"></span></button><button data-action="codex" aria-label="Grimoire"><span class="menu-medallion map-art-4"></span></button>${!active?`<button class="learn-button" data-action="learn" aria-label="Replay the practice route">${icon('wing')}<small>Learn</small></button>`:''}${active?`<button data-action="restart" aria-label="Bank this run and start again">${icon('route')}</button>`:''}</div></div></section>`}
function renderMap(){const r=state.run,total=runLength(r);return `<section class="game-map-screen map-v2 minimal-map"><div class="map-status-strip"><span>${icon('route')}${Math.min(r.step+1,total)}/${total}</span>${heartMarkup(r.hp,r.maxHp||3)}<span>${icon('flame')}${Math.round(r.flame??100)}</span></div>${tutorialCheckpoint()}<div class="map-atlas-frame"><div class="game-map-viewport" id="map-viewport"><svg id="journey-map" class="game-world-map" viewBox="0 0 390 ${mapHeight(r)}" role="group" aria-label="Branching map. Tap a glowing node to inspect. Scroll to scout ahead."></svg></div></div><div class="map-build-dock">${afterglowPanel()}${discoveryProgress()}${miniCards(r.cards)}</div></section>`}
function pixelMapGlyph(kind,x,y){
 const glyphs=[['111111111','110000011','110111011','110101011','110000011','110000011','110000011','111111111'],['000010000','000111000','001111100','000111000','011111110','000111000','111111111','000010000'],['000010000','000111000','001010100','011010110','110010011','111111111','001000100','011111110'],['000111000','001111100','001010100','001111100','001111100','000111000','000010000','001111100'],['000010000','000111000','001101100','011000110','001101100','000111000','000010000','000010000'],['111111111','110111011','110101011','110101011','110101011','110000011','110000011','111111111']];
 const rows=glyphs[kind]||glyphs[0];return `<g shape-rendering="crispEdges" fill="${['#b3ac82','#819378','#9aadb0','#d3a45f','#a99fb7','#b6b9ad'][kind]||'#c4c7a9'}">${rows.map((row,j)=>[...row].map((v,i)=>v==='1'?`<rect x="${x-22+i*5}" y="${y-20+j*5}" width="5" height="5"/>`:'').join('')).join('')}</g>`;
}
function drawMap(){
  const r=state.run,height=mapHeight(r),origin=height-57,svg=document.querySelector('#journey-map');if(!svg)return;
  const choices=getChoices(r),available=new Set(choices.map(n=>n.id)),visited=new Set(r.path),positions={},byId=new Map(r.map.flat().map(n=>[n.id,n]));
  const modern=r.map.some(row=>row.some(n=>Array.isArray(n.nextIds)));
  r.map.forEach((row,i)=>row.forEach((n,j)=>{const lane=modern?(Number.isInteger(n.lane)?n.lane:j):(row.length===2?j*2:1);positions[n.id]={x:[65,195,325][lane]??195,y:height-155-i*145};}));
  const nextNodes=n=>Array.isArray(n.nextIds)?n.nextIds.map(id=>byId.get(id)).filter(Boolean):(r.map[n.row+1]||[]);
  const future=new Set(available),queue=[...choices];while(queue.length){for(const n of nextNodes(queue.shift()))if(!future.has(n.id)){future.add(n.id);queue.push(n);}}
  const takenEdges=new Set(r.path.slice(1).map((id,i)=>`${r.path[i]}|${id}`)),last=r.path.at(-1);
  let paths='',locations='',decorations='',clips='';
  const pathMarkup=(d,taken,open,locked,id)=>`<g class="map-route-line ${taken?'path-taken':open?'path-open':locked?'path-locked':'path-future'}"><path d="${d}" class="route-shadow"/><path id="${id}" d="${d}" class="route-thread"/>${open?`<path d="${d}" class="route-current"/>`:''}</g>`;
  r.map.forEach(row=>row.forEach(a=>{for(const b of nextNodes(a)){const p=positions[a.id],q=positions[b.id];if(!p||!q)continue;const d=`M${p.x} ${p.y-33} C${p.x} ${p.y-79},${q.x} ${q.y+81},${q.x} ${q.y+34}`;paths+=pathMarkup(d,takenEdges.has(`${a.id}|${b.id}`),a.id===last&&available.has(b.id),!future.has(a.id)||!future.has(b.id),`route-${a.id}-${b.id}`);}}));
  const starts=(Array.isArray(r.startNodeIds)?r.startNodeIds:r.map[0].map(n=>n.id)).map(id=>byId.get(id)).filter(Boolean);
  for(const node of starts){const q=positions[node.id],d=`M195 ${origin} C195 ${origin-39},${q.x} ${origin-33},${q.x} ${q.y+34}`;paths+=pathMarkup(d,r.path[0]===node.id,r.path.length===0&&available.has(node.id),r.path.length>0&&r.path[0]!==node.id,`origin-${node.id}`);}
  for(let i=0;i<66;i++){const x=(i*137+41)%390,y=(i*211+73)%height;decorations+=`<circle cx="${x}" cy="${y}" r="${i%5===0?1.6:.7}" fill="#f5dcad" opacity="${.16+(i%4)*.07}"/>`;}
  for(let i=0;i<Math.ceil(runLength(r)*1.3);i++){const x=i%2?320:42,y=170+i*119;decorations+=`<g opacity=".17" transform="translate(${x},${y}) rotate(${i%2?-9:8})"><path d="M-53 8Q-37-12-15-6L8-19 40-7 55 15 26 34-4 47-28 29Z" fill="#323a34"/><path d="M-38 5Q-10-14 33-2" fill="none" stroke="#b8c692" stroke-width="2"/><path d="M-17-8v-29h8v26m20-1v-24h7v27m-42-23q23-23 48 0" fill="none" stroke="#68705d" stroke-width="5"/></g>`;}
  r.map.forEach((row,i)=>row.forEach(n=>{
    const p=positions[n.id],reach=available.has(n.id),taken=visited.has(n.id),bypassed=i<r.step&&!taken,possible=future.has(n.id);
    const art=n.type==='support'?(n.kind==='camp'?3:4):n.type==='finale'?5:({ruins:0,canopy:1,storm:2}[n.terrain]??0);
    const label=n.type==='support'?(n.kind==='camp'?'Sanctuary':n.kind==='shrine'?'Flame shrine':'Moon shrine'):n.type==='finale'?'Hollow Gate':({ruins:'Ancient Ruins',canopy:'Luminous Canopy',storm:'Storm Spires'}[n.terrain]);
    const route=n.type==='support'?(n.kind==='camp'?'REST':n.kind==='shrine'?'REFILL':'EVENT'):n.type==='finale'?'GATE':({refuge:'REFUGE',cavern:'CAVERN',gauntlet:'ELITE'}[n.routeStyle]||(n.elite?'ELITE TRIAL':'PASSAGE'));
    const clip=`map-clip-${n.id}`;clips+=`<clipPath id="${clip}"><circle cx="${p.x}" cy="${p.y}" r="31.5"/></clipPath>`;
    locations+=`<g class="world-map-node ${reach?'reachable':''} ${taken?'taken':''} ${bypassed?'bypassed':''} ${!possible&&!taken?'unreachable':''}" ${reach?`data-action="node" data-id="${esc(n.id)}" role="button" tabindex="0" aria-label="Inspect ${esc(n.name)}. ${esc(n.fuelPreview||n.description)}. ${esc(n.reward)}"`:''}>
      ${reach?`<rect x="${p.x-45}" y="${p.y-43}" width="90" height="122" fill="transparent" pointer-events="all"/>`:''}
      <ellipse cx="${p.x}" cy="${p.y+35}" rx="39" ry="10" fill="#05171e" opacity=".5"/>
      ${reach?`<circle class="node-aureole" cx="${p.x}" cy="${p.y}" r="48" fill="url(#nodeRadiance)"/><circle class="node-pulse" cx="${p.x}" cy="${p.y}" r="38" fill="none" stroke="#ffe6ac" stroke-width="1.5"/><circle cx="${p.x}" cy="${p.y}" r="43" fill="none" stroke="#d9be7c" stroke-opacity=".28"/>`:''}
      <circle cx="${p.x}" cy="${p.y}" r="34" fill="#102e34" stroke="${reach||taken?'#e7c17c':'#6b998b'}" stroke-width="${reach?2:1}"/>
      ${pixelMapGlyph(art,p.x,p.y)}
      ${taken?`<circle cx="${p.x+24}" cy="${p.y+24}" r="10" fill="#e3ba73" stroke="#193f3b" stroke-width="2"/><path d="m${p.x+19} ${p.y+24} 3 3 7-7" fill="none" stroke="#173b35" stroke-width="1.8"/>`:''}
      ${n.elite?`<path d="m${p.x+25} ${p.y-38} 9 10-9 10-9-10Z" fill="#a5563f" stroke="#f3ce91"/><path d="m${p.x+25} ${p.y-34} 0 7m0 3v1" stroke="#ffe7bd" stroke-width="1.5"/>`:''}
      <text x="${p.x}" y="${p.y+56}" class="map-node-name" text-anchor="middle">${esc(label)}</text><text x="${p.x}" y="${p.y+73}" class="map-node-kind" text-anchor="middle">${route}</text>
      ${last===n.id?`<g transform="translate(${p.x},${p.y-52})"><path d="M0-7 5 0 0 8-5 0Z" fill="#ffe1a2"/><circle r="11" fill="none" stroke="#e8c37b" stroke-opacity=".35"/></g>`:''}
    </g>`;
  }));
  svg.innerHTML=`<defs><linearGradient id="atlasSky" x2="0" y2="1"><stop stop-color="#102a3b"/><stop offset=".46" stop-color="#173c3e"/><stop offset="1" stop-color="#0b2930"/></linearGradient><radialGradient id="moonRadiance"><stop stop-color="#e9dbac" stop-opacity=".30"/><stop offset=".35" stop-color="#c1d9c0" stop-opacity=".10"/><stop offset="1" stop-color="#a6d8c9" stop-opacity="0"/></radialGradient><radialGradient id="nodeRadiance"><stop stop-color="#f5cd81" stop-opacity=".27"/><stop offset=".63" stop-color="#f5cd81" stop-opacity=".10"/><stop offset="1" stop-color="#f5cd81" stop-opacity="0"/></radialGradient><linearGradient id="mapIsland" x2=".4" y2="1"><stop stop-color="#7f9d85"/><stop offset="1" stop-color="#173544"/></linearGradient><pattern id="atlasContour" width="195" height="220" patternUnits="userSpaceOnUse"><path d="M-30 80Q27 12 107 75T235 72M-30 95Q27 27 107 90T235 87M-30 112Q27 44 107 107T235 104" stroke="#a2bc9d" stroke-opacity=".05" fill="none"/></pattern>${clips}</defs><rect width="390" height="${height}" fill="url(#atlasSky)"/><rect width="390" height="${height}" fill="url(#atlasContour)"/><circle cx="195" cy="90" r="155" fill="url(#moonRadiance)"/><circle cx="195" cy="88" r="26" fill="#e9d8a5" opacity=".72"/><circle cx="205" cy="80" r="24" fill="#193641"/><path d="M24 64Q195 8 366 64M24 ${height-18}Q195 ${height+24} 366 ${height-18}" stroke="#9eae8866" stroke-width="1" fill="none"/>${decorations}${paths}${locations}<g transform="translate(195,${origin})"><circle r="23" fill="url(#nodeRadiance)"/><path d="M0-13C3-5 12-3 9 6 6 17-10 16-10 5-10 1-7-2-4-6-5 1-1 2 0-13Z" fill="#e9be77"/><circle r="24" fill="none" stroke="#b79d6855"/></g><text x="195" y="36" class="map-gate-title" text-anchor="middle">${r.isTutorial?'FIRST LIGHT':'THE HOLLOW GATE'}</text><text x="195" y="${height-17}" class="map-origin-label" text-anchor="middle">EVERY GLOW CHOOSES ITS OWN PATH</text>`;
  const viewport=document.querySelector('#map-viewport'),target=positions[choices[0]?.id];
  if(viewport&&target){const ratio=svg.getBoundingClientRect().width/390;viewport.scrollTop=Math.max(0,target.y*ratio-viewport.clientHeight*.62);}
}

function rewardBanner(){const r=state.run,f=r?.lastFlight;if(r?.phase!=='reward'||r.current?.type==='support'||!f)return '';return `<div class="reward-banner">${icon('check')}<span>${icon('ember')}+${(f.completionBonus||0)+(f.challengeBonus||0)}</span><span>${icon('flame')}${Math.round(r.flame??100)}</span></div>${afterglowChange(f.afterglow)}${discoveryCue()}`}
function cardArt(c){const index=cardList().findIndex(item=>item.id===c.id),col=index%4,row=Math.floor(index/4);return `<span class="illustrated-card-icon" style="background-position:${col*100/3}% ${row*50}%" aria-hidden="true"></span>`}
document.addEventListener('keydown',e=>{const target=e.target.closest?.('.world-map-node[role="button"]');if(target&&['Enter',' '].includes(e.key)){e.preventDefault();selectNode(state.run,target.dataset.id);persist();goToRun()}});
render();
